class Solution {
  public int sumOfGoodSubsequences(int[] nums) {
    final long MOD = 1_000_000_007L;
    int max = 0;
    for (int v : nums) max = Math.max(max, v);
    long[] cnt = new long[max + 3], sum = new long[max + 3];
    long ans = 0;
    for (int v : nums) {
      int i = v + 1;
      long c = (1 + cnt[i - 1] + cnt[i + 1]) % MOD;
      long s = (v * c + sum[i - 1] + sum[i + 1]) % MOD;
      cnt[i] = (cnt[i] + c) % MOD;
      sum[i] = (sum[i] + s) % MOD;
      ans = (ans + s) % MOD;
    }
    return (int) ans;
  }
}
